mapper.select:
SELECT s.*  
AND s.drama_id = #{dramaId}
AND s.episode_id = #{episodeId}
AND s.scene_id = #{sceneId}
ORDER BY ep.episode_no, sc.scene_no, s.sort_order, s.shot_no, s.id

SELECT sc.* 
AND sc.drama_id = #{dramaId}
AND sc.episode_id = #{episodeId}
AND sc.id = #{sceneId}
ORDER BY sc.episode_id, sc.scene_no, sc.id

SELECT g.* FROM drama_shot_group g
JOIN drama d ON d.id = g.drama_id AND d.deleted = 0
JOIN drama_scene sc ON sc.id = g.scene_id AND sc.drama_id = g.drama_id AND sc.deleted = 0
JOIN drama_episode ep ON ep.id = g.episode_id AND ep.id = sc.episode_id AND ep.drama_id = g.drama_id AND ep.deleted = 0
WHERE g.deleted = 0 AND g.drama_id = #{dramaId}
AND g.episode_id = #{episodeId}
AND g.scene_id = #{sceneId}
ORDER BY g.episode_id, g.group_no, g.id
